// ============================ SETTINGS ============================
const ModelName  = 'gemini-3.1-flash-lite';   // free tier: 500 requests per day
const SecretCode = '';                        // same as "Secret code" in the app. Empty = no check
// ==================================================================

// What we tell Gemini. One line per rule so it is easy to edit.
const PromptText = [
  'You listen to one short voice command for an appointment calendar.',
  'The speaker uses Russian, English or Dutch (detect it yourself, they may mix languages).',
  'Return JSON only.',
  '',
  'intent:  "create" if the speaker wants to add an appointment, otherwise "none".',
  'heard:   exact transcript, in the spoken language.',
  'kind:    how the DATE was said: "relative" (tomorrow, in 6 weeks, over 2 maanden, через неделю),',
  '         "weekday" (on Friday, next Monday, volgende dinsdag, в пятницу),',
  '         "absolute" (18 November, 3 mei, 5 января) or "none" if no date was said.',
  'relative: amount + unit (days, weeks, months, years). today = 0 days, tomorrow = 1 days, next week = 1 weeks.',
  'weekday:  1 = Monday ... 7 = Sunday. which = "next" if the speaker said next / volgende / следующий, else "this".',
  'absolute: day, month (1-12), year only if spoken (else 0).',
  'time:    24h "HH:MM", or "" if no time was said. "half past two" = 14:30, "kwart over drie" = 15:15.',
  '         Without am/pm, hours 1-7 mean afternoon (13:00-19:00), hours 8-12 stay as spoken.',
  'text:    ONLY the name of the person the appointment is for (first name, or first + last name).',
  '         Ignore the service, greetings, filler words and everything else. Use "" if no name was said.',
  'Unused number fields = 0, unused text fields = "".',
].join('\n');

// The answer format Gemini has to follow
function BuildSchema() {
  const text = { type: 'STRING' };
  const number = { type: 'INTEGER' };
  return {
    type: 'OBJECT',
    properties: {
      intent:  { type: 'STRING', enum: ['create', 'none'] },
      heard:   text,
      kind:    { type: 'STRING', enum: ['relative', 'weekday', 'absolute', 'none'] },
      amount:  number,
      unit:    { type: 'STRING', enum: ['days', 'weeks', 'months', 'years'] },
      weekday: number,
      which:   { type: 'STRING', enum: ['this', 'next'] },
      day:     number,
      month:   number,
      year:    number,
      time:    text,
      text:    text,
    },
    required: ['intent', 'heard', 'kind', 'amount', 'unit', 'weekday', 'which', 'day', 'month', 'year', 'time', 'text'],
  };
}

function BuildGeminiRequest(body) {
  const clock = `Today is ${body.weekday}, ${body.today}. Local time ${body.time_now}. Time zone ${body.tz}.`;
  return {
    systemInstruction: { parts: [{ text: PromptText }] },
    contents: [{
      role: 'user',
      parts: [
        { inlineData: { mimeType: body.mime || 'audio/aac', data: body.audio } },
        { text: clock },
      ],
    }],
    generationConfig: {
      temperature: 0,
      responseMimeType: 'application/json',
      responseSchema: BuildSchema(),
    },
  };
}

function Main() {
  const request = $input.first().json;
  const headers = request.headers || {};
  const body = request.body || {};

  if (SecretCode && headers['x-token'] !== SecretCode) throw new Error('Wrong secret code');
  if (!body.audio) throw new Error('No audio received');

  return [{ json: { model: ModelName, gemini: BuildGeminiRequest(body), today: body.today } }];
}

return Main();

// Gemini only understands the sentence. The date maths is done here, so it is always exact.

const MsPerDay = 24 * 60 * 60 * 1000;

// only the name is kept: at most the first two words
function KeepName(text) {
  return (text || '').trim().split(/\s+/).slice(0, 2).join(' ');
}

function Fail(message, heard) {
  return [{ json: { ok: false, heard: heard || '', message } }];
}

function ParseReply(reply) {
  try {
    return JSON.parse(reply.candidates[0].content.parts[0].text);
  } catch (error) {
    return null;
  }
}

function AddDays(date, days) {
  return new Date(date.getTime() + days * MsPerDay);
}

// 31 January + 1 month = 28 February (never jumps into the next month)
function AddMonthsClamped(date, months) {
  const result = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + months, 1));
  const lastDay = new Date(Date.UTC(result.getUTCFullYear(), result.getUTCMonth() + 1, 0)).getUTCDate();
  result.setUTCDate(Math.min(date.getUTCDate(), lastDay));
  return result;
}

function ToIsoDate(date) {
  const month = String(date.getUTCMonth() + 1).padStart(2, '0');
  const day = String(date.getUTCDate()).padStart(2, '0');
  return `${date.getUTCFullYear()}-${month}-${day}`;
}

// "in 6 weeks", "tomorrow", "over 2 maanden"
function ResolveRelative(today, data) {
  const amount = data.amount || 0;
  switch (data.unit) {
    case 'days':   return AddDays(today, amount);
    case 'weeks':  return AddDays(today, amount * 7);
    case 'months': return AddMonthsClamped(today, amount);
    case 'years':  return AddMonthsClamped(today, amount * 12);
    default:       return null;
  }
}

// "on Friday", "next Monday"
function ResolveWeekday(today, data) {
  if (data.weekday < 1 || data.weekday > 7) return null;

  const todayNumber = ((today.getUTCDay() + 6) % 7) + 1;   // Monday = 1 ... Sunday = 7
  let daysAhead = (data.weekday - todayNumber + 7) % 7;
  if (daysAhead === 0) daysAhead = 7;                      // same weekday means next week

  const stillThisWeek = daysAhead <= 7 - todayNumber;
  if (data.which === 'next' && stillThisWeek) daysAhead += 7;
  return AddDays(today, daysAhead);
}

// "18 November", "5 января"
function ResolveAbsolute(today, data) {
  if (!data.day || !data.month) return null;

  const year = data.year || today.getUTCFullYear();
  let date = new Date(Date.UTC(year, data.month - 1, data.day));
  if (!data.year && date < today) date = new Date(Date.UTC(year + 1, data.month - 1, data.day));
  return date;
}

function ResolveDate(today, data) {
  switch (data.kind) {
    case 'relative': return ResolveRelative(today, data);
    case 'weekday':  return ResolveWeekday(today, data);
    case 'absolute': return ResolveAbsolute(today, data);
    default:         return null;
  }
}

function Main() {
  const reply = $input.first().json;
  const todayText = $('Prepare request').first().json.today;   // yyyy-mm-dd, sent by the phone
  const today = new Date(todayText + 'T00:00:00Z');

  const data = ParseReply(reply);
  if (!data) return Fail('I could not read the answer');
  if (data.intent !== 'create') return Fail('I did not hear an appointment', data.heard);

  const date = ResolveDate(today, data);
  if (!date) return Fail('I did not hear a date', data.heard);

  return [{
    json: {
      ok: true,
      date: ToIsoDate(date),
      time: data.time || '',
      text: KeepName(data.text),
      heard: data.heard,
    },
  }];
}

return Main();
